source11='''from collections import Counter

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    marked=[(r,c) for r in range(rows) for c in range(cols) if grid[r][c]==8]
    r0=min(r for r,_ in marked); r1=max(r for r,_ in marked)
    c0=min(c for _,c in marked); c1=max(c for _,c in marked)
    candidates=[]
    if all(0<=31-r<rows for r in range(r0,r1+1)):
        h=[[grid[31-r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
        if all(x!=8 for row in h for x in row): candidates.append(h)
    if all(0<=31-c<cols for c in range(c0,c1+1)):
        v=[[grid[r][31-c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
        if all(x!=8 for row in v for x in row): candidates.append(v)
    if candidates: return candidates[0]
    out=[[grid[31-r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    modes=[]
    for c in range(c0,c1+1):
        vals=[grid[r][c] for r in range(rows) if grid[r][c]!=8]
        modes.append(Counter(vals).most_common(1)[0][0] if vals else 0)
    for i,r in enumerate(range(r0,r1+1)):
        for j,c in enumerate(range(c0,c1+1)):
            if out[i][j]==8:
                out[i][j]=grid[r][31-c] if 0<=31-c<cols else modes[j]
    return out
